import 'package:flutter/material.dart';
import 'package:liquid_glass_bottom_bar/liquid_glass_bottom_bar.dart';

class MyScreen extends StatefulWidget {
  const MyScreen({super.key});
  @override
  State<MyScreen> createState() => _MyScreenState();
}

class _MyScreenState extends State<MyScreen> {
  int _currentIndex = 0;
  final _pages = const [Center(child: Text('Home')), Center(child: Text('Search')), Center(child: Text('Profile'))];
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      extendBody: true,
      appBar: AppBar(title: const Text('Liquid Glass Demo')),
      body: IndexedStack(index: _currentIndex, children: _pages),
      bottomNavigationBar: LiquidGlassBottomBar(
        items: const [
          LiquidGlassBottomBarItem(icon: Icons.home_outlined, activeIcon: Icons.home, label: 'Home'),
          LiquidGlassBottomBarItem(icon: Icons.search_outlined, label: 'Search'),
          LiquidGlassBottomBarItem(icon: Icons.person_outline, activeIcon: Icons.person, label: 'Profile', badge: 5),
        ],
        currentIndex: _currentIndex,
        onTap: (i) => setState(() => _currentIndex = i),
        activeColor: Color(0xFF34C3FF),
        barBlurSigma: 16,
        activeBlurSigma: 24,
      ),
    );
  }
}
